    'STRONG ALIGNMENT': isEn ? 'Strong Alignment' : 'Alineacion fuerte',
    'SOLID ALIGNMENT WITH COACHING': isEn ? 'Solid Alignment With Coaching' : 'Alineacion solida con coaching',
