+  }
+
+  const failOnBreach = String(process.env.QA_GATE_FAIL_ON_BREACH || 'false').toLowerCase() === 'true';
+  if (failOnBreach && breaches.length) {
+    process.exit(1);
+  }
+}
+
+main();
