};

function getTargetRoleOptions(isEn) {
  return [
    { value: 'generalist', label: isEn ? 'Generalist (Balanced)' : 'Generalista (balanceado)' },
    { value: 'analyst', label: isEn ? 'Analyst / Data' : 'Analista / Datos' },
